 1	mod indicators;
 2	
 3	use indicators::{Percentage, ProgressDisplay};
 4	use std::num::IntErrorKind;
 5	
 6	fn abort_stoi(exception: &str) -> ! {
 7	    eprintln!(
 8	        "terminate called after throwing an instance of '{}'\n  what():  stoi",
 9	        exception
10	    );
11	    std::process::abort();
12	}
13	
14	fn parse_progress_arg(raw: &str) -> i32 {
15	    let trimmed = raw.trim_start();
16	    let bytes = trimmed.as_bytes();
17	    let mut end = 0usize;
18	
19	    if let Some(first) = bytes.first() {
20	        if *first == b'+' || *first == b'-' {
21	            end = 1;
22	        }
23	    }
24	
25	    let digits_start = end;
26	    while end < bytes.len() && bytes[end].is_ascii_digit() {
27	        end += 1;
28	    }
29	
30	    if end == digits_start {
31	        abort_stoi("std::invalid_argument");
32	    }
33	
34	    match trimmed[..end].parse::<i32>() {
35	        Ok(value) => value,
36	        Err(err) => match err.kind() {
37	            IntErrorKind::PosOverflow | IntErrorKind::NegOverflow => {
38	                abort_stoi("std::out_of_range")
39	            }
40	            _ => abort_stoi("std::invalid_argument"),
41	        },
42	    }
43	}
44	
45	fn main() {
46	    let mut display = ProgressDisplay::new(200);
47	    let progress = std::env::args()
48	        .nth(1)
49	        .map_or(150, |raw| parse_progress_arg(&raw));
50	
51	    display.update(progress);
52	    println!("{}", display.display());
53	
54	    display.increment(25);
55	    println!("{}", display.display());
56	
57	    let pct1 = Percentage::new(0.15_f32, 1);
58	    let pct2 = Percentage::new(0.35_f32, 2);
59	    let pct3 = Percentage::new(0.65_f32, 3);
60	
61	    println!("{}", pct1.str());
62	    println!("{}", pct2.str());
63	    println!("{}", pct3.str());
64	}

 1	pub struct ProgressDisplay {
 2	    total: i32,
 3	    progress: i32,
 4	}
 5	
 6	impl ProgressDisplay {
 7	    pub fn new(total: i32) -> Self {
 8	        Self { total, progress: 0 }
 9	    }
10	
11	    pub fn update(&mut self, progress: i32) {
12	        self.progress = progress;
13	    }
14	
15	    pub fn increment(&mut self, amount: i32) {
16	        self.progress += amount;
17	    }
18	
19	    pub fn display(&self) -> String {
20	        let percentage = (self.progress as f64 / self.total as f64) * 100.0;
21	        format!(
22	            "Progress: {:.1}% ({}/{})",
23	            percentage, self.progress, self.total
24	        )
25	    }
26	}

 1	pub struct Percentage {
 2	    value: f32,
